INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Verschlüsselung nur für sensible Daten nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Daten können geschützt werden"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz sinnvoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Verschlüsselung?', 3, '[{"text": "Datensicherheit", "correct": true, "because": "Schutz vor unbefugtem Zugriff"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien gehören zur Verschlüsselung?', 5, '[{"text": "AES", "correct": true, "because": "Symmetrische Verschlüsselung"}, {"text": "TLS", "correct": true, "because": "Sichert Datenübertragung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) TLS schützt die Übertragung. b) AES ist nur für Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "AES auch für lokale Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verschlüsselung?', 4, '[{"text": "Schlüsselmanagement", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Algorithmusstärke", "correct": false, "because": "Wichtig für Schutz"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Verschlüsselung auch Integrität schützt?', 2, '[{"text": "Nein", "correct": true, "because": "Primär Vertraulichkeit"}, {"text": "Ja", "correct": false, "because": "Integrität durch andere Mittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren ist symmetrisch?', 3, '[{"text": "AES", "correct": true, "because": "Ein Schlüssel für Ver-/Entschlüsselung"}, {"text": "RSA", "correct": false, "because": "Asymmetrisch"}, {"text": "TLS", "correct": false, "because": "Kombination möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden sichern Daten effektiv?', 5, '[{"text": "SSL", "correct": true, "because": "Sichert Übertragung"}, {"text": "PGP", "correct": true, "because": "Verschlüsselt E-Mails"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Unsortierte Daten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Verschlüsselung schützt vor Abhören. b) Sie ist ohne Schlüssel möglich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schlüssel sind essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Verschlüsselung?', 4, '[{"text": "Schlüssel", "correct": false, "because": "Notwendig für Ver-/Entschlüsselung"}, {"text": "Algorithmus", "correct": false, "because": "Technische Basis"}, {"text": "Maximale Speichergröße", "correct": true, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist AES asymmetrisch?', 2, '[{"text": "Nein", "correct": true, "because": "Symmetrische Verschlüsselung"}, {"text": "Ja", "correct": false, "because": "Ein Schlüssel genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien schützen die Übertragung?', 4, '[{"text": "TLS", "correct": true, "because": "Standard für sichere Kommunikation"}, {"text": "IPSec", "correct": true, "because": "Sichert Netzwerke"}, {"text": "Großer Cache", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Verschlüsselung immer langsam ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Moderne Algorithmen sind effizient"}, {"text": "Ja", "correct": false, "because": "Leistung optimierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verschlüsselung?', 3, '[{"text": "Schlüsselstärke", "correct": true, "because": "Entscheidet über Sicherheit"}, {"text": "Schnelle Server", "correct": false, "because": "Sekundär"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) RSA ist asymmetrisch. b) TLS ist nur für Websites.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TLS auch für andere Protokolle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Algorithmen sind für Verschlüsselung üblich?', 5, '[{"text": "AES-256", "correct": true, "because": "Starke symmetrische Verschlüsselung"}, {"text": "SHA-256", "correct": false, "because": "Hashing, nicht Verschlüsselung"}, {"text": "RSA", "correct": true, "because": "Asymmetrische Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verschlüsselung unwichtig?', 3, '[{"text": "Schlüsselverwaltung", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Algorithmuswahl", "correct": false, "because": "Bestimmt Schutz"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt Verschlüsselung auch vor Manipulation?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Vertraulichkeit"}, {"text": "Ja", "correct": false, "because": "Integrität separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob TLS auch Authentizität bietet?', 2, '[{"text": "Ja", "correct": true, "because": "Zertifikate verifizieren Identität"}, {"text": "Nein", "correct": false, "because": "Mehr als nur Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren wähle ich für sichere Dateien?', 4, '[{"text": "AES", "correct": true, "because": "Effizient für lokale Daten"}, {"text": "Hohe Latenz", "correct": false, "because": "Kein Schutz"}, {"text": "Großer Speicher", "correct": false, "because": "Irrelevant"}]');
